// The facts pve01 counted (phoenix-lab-report). Problems and the subject are decided here and there,
// never by the model: it only writes the summary.
const f = $input.first().json.body;
const esc = s => String(s ?? '').replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;');
const day = (f.generated || '').slice(0, 10);
const subject = `Lab report ${day}: ${f.issues.length ? f.status : 'all OK'}`;

const list = (title, items) => items && items.length ? `<h3>${title}</h3><ul>${items.map(i => `<li>${esc(i)}</li>`).join('')}</ul>` : '';
const table = (title, rows, cols) => !rows || !rows.length ? '' :
  `<h3>${title}</h3><table border="1" cellpadding="4" cellspacing="0" style="border-collapse:collapse;font-size:13px">` +
  `<tr>${cols.map(c => `<th align="left">${esc(c[0])}</th>`).join('')}</tr>` +
  rows.map(r => `<tr>${cols.map(c => `<td>${esc(typeof c[1] === 'function' ? c[1](r) : r[c[1]])}</td>`).join('')}</tr>`).join('') + '</table>';

const h = f.host || {};
const factsHtml = [
  list('Issues', f.issues), list('Notes', f.notes), list('Checks that failed to run', f.check_errors),
  `<h3>Host</h3><p>${esc(h.pve)}<br>Up ${esc(h.uptime_days)} days, kernel ${esc(h.kernel)}; ${esc(h.pending_updates)} updates pending; failed units: ${esc((h.failed_units || []).join(', ') || 'none')}</p>`,
  table('Guests', f.guests, [['ID', 'vmid'], ['Name', 'name'], ['Type', 'type'], ['Status', 'status'], ['Up (days)', 'uptime_days'], ['Starts at boot', r => r.onboot ? 'yes' : 'no']]),
  table('Backup runs (last 26 hours)', (f.backups || {}).runs, [['Started', 'started'], ['Minutes', 'minutes'], ['Status', 'status'], ['Failed guests', r => (r.failed_guests || []).join(', ')]]),
  table('PBS jobs (last 26 hours)', Object.entries(f.pbs || {}).map(([k, v]) => ({ k, ...v })), [['Job', 'k'], ['Runs', 'runs'], ['Not OK', 'not_ok']]),
  table('Storage', f.storage, [['Storage', 'id'], ['Type', 'type'], ['Active', r => r.active ? 'yes' : 'NO'], ['Used', r => Math.round(r.used * 100) + '%'], ['Size (GB)', 'total_gb']]),
  table('ZFS pools', f.zfs, [['Pool', 'pool'], ['Health', 'health'], ['Used', r => r.cap_pct + '%'], ['Size (GB)', 'size_gb'], ['Last scrub (days)', r => r.last_scrub_days ?? 'none yet'], ['Errors', 'errors']]),
  table('Disks', f.disks, [['Device', 'device'], ['Model', 'model'], ['SMART', r => r.passed === false ? 'FAILED' : 'passed'], ['Temp (°C)', r => r.temp_c ?? '-'], ['Wear', r => r.wear_pct == null ? '-' : r.wear_pct + '%'], ['Reallocated', r => r.reallocated ?? '-'], ['Defects', r => r.grown_defects ?? '-']]),
  table('Certificates (days left)', Object.entries(f.certificates || {}).map(([k, v]) => ({ k, v })), [['Certificate', 'k'], ['Days', 'v']]),
  table(`Firewall drops, last 24 hours: ${(f.firewall || {}).dropped_24h ?? '?'} in ${(f.firewall || {}).distinct_flows ?? '?'} flows (top 10)`, (f.firewall || {}).top, [['Guest', 'guest'], ['Source', 'src'], ['Destination', 'dst'], ['Protocol', 'proto'], ['Port', 'dport'], ['Count', 'count']]),
].join('\n');

// What the model sees: the decided problems and notes, plus the facts in compact form.
const compact = { generated: f.generated, status: f.status, issues: f.issues, notes: f.notes, check_errors: f.check_errors,
  host: h, guests: f.guests, backups: f.backups, pbs: f.pbs, storage: f.storage, zfs: f.zfs,
  disks: (f.disks || []).map(d => ({ model: d.model, device: d.device, temp_c: d.temp_c, wear_pct: d.wear_pct, passed: d.passed })),
  certificates: f.certificates, firewall: f.firewall };
const prompt = `You write the morning health summary of a home lab's Proxmox server (pve01) for its administrator.
Rules: use ONLY the facts below; never invent numbers, names or causes. The ISSUES list is authoritative: every
issue must appear, none may be added. Write plain text, at most 10 short lines:
1. One line: the verdict (all OK, or how many issues).
2. Each issue: what it means and the obvious next step, in one or two lines.
3. Only then, at most three notes worth knowing (trends, things coming up), if any.
No greeting, no sign-off, no tables, no markdown headings.

FACTS (JSON):
${JSON.stringify(compact)}`;

return [{ json: { subject, prompt, factsHtml } }];

// The summary first (or a note that it's missing), then every fact, so nothing depends on the model.
const p = $('Prepare').first().json;
const text = $input.first().json.text;
const esc = s => String(s ?? '').replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;');
const summary = text && String(text).trim()
  ? `<pre style="font-family:inherit;white-space:pre-wrap;font-size:14px">${esc(String(text).trim())}</pre>`
  : '<p><b>Summary unavailable</b> (the model on ai01 didn\'t answer); the facts below are complete.</p>';
const html = `<div style="font-family:sans-serif">${summary}<hr><p style="color:#666;font-size:12px">Summary by gpt-oss-120b on ai01; the facts and problems below are counted by phoenix-lab-report on pve01.</p>${p.factsHtml}</div>`;
return [{ json: { subject: p.subject, html } }];
